-- Verified Georgia Secretary of State 2026 General Election US Senate county totals
-- Source: official SOS report 2026-11-03-general-and-special-election.xlsx

ALTER TABLE public.county_voter_statistics DROP CONSTRAINT IF EXISTS county_voter_statistics_election_year_check;
ALTER TABLE public.county_voter_statistics ADD CONSTRAINT county_voter_statistics_election_year_check CHECK (election_year >= 2000 AND election_year <= 2030);

